6	const SPHINX = "sphinx";
7	const BASE_SPHINX_SCORE = 2;
8	const BONUS_SPHINX_SCORE = 3;
9	const NO_SPHINX_SCORE = 0;
10	const BONUS_TYPE_THRESHOLD = 3;
11	
12	export const scoreArmy = (army: Card[]): number => {
13	  const monsters = army.map((card) => card.monster);
14	  if (!monsters.includes(SPHINX)) return NO_SPHINX_SCORE;
15	
16	  const distinctTypeCount = new Set(monsters).size;
17	  if (distinctTypeCount <= BONUS_TYPE_THRESHOLD) return BASE_SPHINX_SCORE;
18	
19	  const typesBeyondThree = distinctTypeCount - BONUS_TYPE_THRESHOLD;
20	  return 2 * typesBeyondThree - 1;
21	};
